{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddr, colIndex } from './addr.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const a = parseAddr(raw)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content })
}

const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out.push(`${c.key}=${sheet.format(sheet.get(c.key))}`)
} else {
  for (const c of sorted) {
    let line = `${c.key}:`
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        collect(ast, set)
        const ds = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of ds) line += ' ' + d.key
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')

function collect(n, set) {
  switch (n.t) {
    case 'ref': {
      const a = parseAddr(n.name)
      if (a) set.set(a.key, a)
      break
    }
    case 'range': {
      const a = parseAddr(n.a)
      const b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
            const x = parseAddr(null, c, r)
            set.set(x.key, x)
          }
      }
      break
    }
    case 'bin':
      collect(n.l, set)
      collect(n.r, set)
      break
    case 'neg':
    case 'pos':
      collect(n.x, set)
      break
    case 'call':
      for (const x of n.args) collect(x, set)
      break
  }
}
