{"file_path":"src/parse.js","content":"function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the text.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = new Error('syntax')
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-')) { p++; return { t: 'neg', x: unary() } }
    if (isOp('+')) { p++; return { t: 'pos', x: unary() } }
    return atom()
  }
  function atom() {
    if (p >= toks.length) throw fail
    const tk = toks[p++]
    if (tk.k === 'num') return { t: 'num', v: tk.v }
    if (tk.k === 'op') {
      if (tk.v !== '(') throw fail
      const e = cmp()
      if (!isOp(')')) throw fail
      p++
      return e
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw fail
        }
      }
      return { t: 'call', name: tk.v.toUpperCase(), args }
    }
    const up = tk.v.toUpperCase()
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw fail
      return { t: 'range', a: tk.v, b: toks[p++].v }
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', name: tk.v }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === fail) return null
    throw e
  }
}
"}

